import "./oderlist.css";
import { useCart } from "./CartContext";
import { useNavigate } from "react-router-dom";

const OrderList = () => {
    const { orders, setOrders } = useCart(); // ✅ Lấy setOrders từ context
    const navigate = useNavigate();

    // Xử lý đặt hàng
    const handlePlaceOrder = () => {
        alert("Đặt hàng thành công!");
        setOrders([]); // ✅ Xóa đơn hàng sau khi đặt (nếu cần)
        navigate("/cart");
    };

    if (!orders || orders.length === 0) {
        return <p>Chưa có đơn hàng nào.</p>;
    }

    return (
        <div className="order-list">
            <h2>Thông tin giao hàng</h2>
            {orders.map((order) => (
                <div key={order.id} className="order-item">
                    <p></p>

                    <div className="container">
                        <div className="square-box">
                            <span className="box-title">Thông tin</span>
                            <span className="box-content"></span>
                        </div>
                        <div className="square-box">
                            <span className="box-title">Họ & Tên</span>
                            <span className="box-content"></span>
                        </div>
                        <div className="square-box">
                            <span className="box-title">Địa chỉ</span>
                            <span className="box-content"></span>
                        </div>
                        <div className="square-box">
                            <span className="box-title">Tỉnh</span>
                            <span className="box-content"></span>
                        </div>
                        <div className="square-box">
                            <span className="Note">Ghi chú</span>
                            <span className="box-content">Nhập ghi chú</span>
                        </div>

                    </div>


                    <p>📅 Ngày đặt: {order.date}</p>
                    <p>💵 Tổng tiền: {order.total}k</p>
                    <div className="order-items">
                        {order.items.map((item, index) => (
                            <div key={index} className="order-item-details">
                                <img src={item.image} alt={item.name} className="order-item-image"/>
                                <span>{item.name} - {item.price}k</span>
                            </div>
                        ))}
                    </div>
                </div>
            ))}
            <button className="place-order-btn" onClick={handlePlaceOrder}>Đặt hàng</button>
        </div>
    );
};

export default OrderList;
